query FindManyTimelineActivities($filter: TimelineActivityFilterInput, $orderBy: [TimelineActivityOrderByInput], $lastCursor: String, $limit: Int, $offset: Int) {
  timelineActivities(
    filter: $filter
    orderBy: $orderBy
    first: $limit
    after: $lastCursor
    offset: $offset
  ) {
    edges {
      node {
        __typename
        createdAt
        createdBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        deletedAt
        happensAt
        id
        linkedObjectMetadataId
        linkedRecordId
        position
        properties
        timelineActivityTypeId
        timelineActivityTypeSnapshot
        updatedAt
        updatedBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        workspaceMember {
          __typename
          avatarUrl
          id
          name {
            firstName
            lastName
            __typename
          }
        }
        workspaceMemberId
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
